  extern AppConfig* g_app_config; // Assume global config is accessible

- void log_message(const char* tag, const char* message) {
-     // Old implementation
-     fprintf(stdout, "[%s] %s\n", tag, message);
- }
+
+ void log_message(LogLevel level, const char* tag, const char* format, ...) {
+     if (!g_app_config || level < g_app_config->log_level) {
+         return; // Do not log if level is below configured level
+     }
+
+     char buffer[1024];
+     va_list args;
+     va_start(args, format);
+     vsnprintf(buffer, sizeof(buffer), format, args);
+     va_end(args);
+
+     // You would also map the enum back to a string for printing
+     const char* level_str = "INFO";
+     if (level == LOG_LEVEL_DEBUG) level_str = "DEBUG";
+     if (level == LOG_LEVEL_ERROR) level_str = "ERROR";
+
+     fprintf(stdout, "[%s] [%s] %s\n", level_str, tag, buffer);
+ }

